/**
 * Auto-generated blog posts: ten Arabic articles about the Egyptian Exchange
 * (EGX) written once a day (see /api/cron/blog-generate in server.js,
 * triggered by .github/workflows/blog-cron.yml) and held as drafts until an
 * admin approves them (see /api/admin/blog-drafts).
 *
 * Two-stage daily workflow:
 *  1. discoverTopics() researches EGX news once and clusters it into 10
 *     distinct (primary keyword, news angle) pairs — one per article, no
 *     overlap.
 *  2. generateArticle() writes, reviews, and stores one article per topic.
 *
 * Mirrors marketAnalysis.js's cache-or-generate shape: one generation per
 * (post_date, batch_index), read afterward by every visitor rather than
 * regenerated per request. See getOrGenerateDailyBlogBatch, which callers
 * should use instead of calling the pieces directly.
 */

import { z } from 'zod';
import { requestStructuredOR } from './clientOpenRouter.js';
import { getBlogPostByBatch, getBlogPostsForDate, insertBlogPostDraft } from '../db.js';

// Pinned independently of ALYTIC_MODEL: the blog generator always wants a
// model with real web-search tool support, regardless of what the
// portfolio-analysis features are configured to use.
// qwen/qwen3-235b-a22b:free was pulled by OpenRouter (verified live, 2026-09-11
// — 404 telling callers to use the paid slug instead); nvidia/nemotron-3-ultra
// confirmed still free via `GET /models` against the real API key in prod.
const BLOG_MODEL = process.env.BLOG_MODEL ?? 'nvidia/nemotron-3-ultra-550b-a55b:free';
// Second, independent model that reviews each draft before it reaches the
// admin approval queue — see reviewBlogPost.
const BLOG_REVIEW_MODEL = process.env.BLOG_REVIEW_MODEL ?? 'google/gemma-4-31b-it:free';

// Exactly 10 articles/day, per the editorial brief this generator follows.
const ARTICLES_PER_DAY = 10;
const MIN_WORDS = 500;
const MAX_WORDS = 1000;

// Required verbatim on every article — never generated by the model (which
// could paraphrase or mistranslate it), always appended in code so it's
// guaranteed to reach storage unchanged.
const CTA_TEXT = 'سجل محفتك وتابعها اول بأول من شاشة واحده egxpert.com';

const TopicSchema = z.object({
  primaryKeyword: z
    .string()
    .describe('High-search-volume Arabic keyword/phrase this article targets — must be distinct from every other topic in the batch'),
  secondaryKeywords: z
    .array(z.string())
    .min(2)
    .max(6)
    .describe('Related Arabic keywords/phrases to weave through the article body without stuffing'),
  newsAngle: z
    .string()
    .describe('One or two Arabic sentences on the specific, current, verifiable EGX story this article will cover (a company disclosure, index move, FRA decision, IPO news, dividend, etc.) — not a generic topic'),
});

const TopicPlanSchema = z.object({
  topics: z
    .array(TopicSchema)
    .length(ARTICLES_PER_DAY)
    .describe(`Exactly ${ARTICLES_PER_DAY} distinct EGX news angles for today, each targeting a unique primary keyword with no overlap between articles`),
});

const ContentBlockSchema = z.discriminatedUnion('type', [
  z.object({ type: z.literal('heading'), level: z.union([z.literal(2), z.literal(3)]), text: z.string() }),
  z.object({ type: z.literal('paragraph'), text: z.string() }),
  z.object({ type: z.literal('list'), items: z.array(z.string()) }),
]);

export const BlogPostSchema = z.object({
  title: z.string().describe('Arabic H1 headline, specific and newsy — not generic — naturally including the primary keyword'),
  slug: z
    .string()
    .describe('URL slug: lowercase Latin letters, numbers and hyphens only, transliterated/English (e.g. "comi-q3-earnings-egx30"), no Arabic script'),
  metaDescription: z
    .string()
    .describe('Arabic meta description, 140-160 characters exactly, including the primary keyword'),
  dek: z.string().describe('One-sentence Arabic subheading/summary for list pages and social previews'),
  content: z
    .array(ContentBlockSchema)
    .min(6)
    .describe(
      `The article body as a sequence of blocks (heading/paragraph/list) totalling ${MIN_WORDS}-${MAX_WORDS} Arabic words — do not include the closing call-to-action, it is appended separately. Use level-2 headings for main sections and level-3 for subsections; the primary keyword must appear naturally in at least one heading and within the first 100 words of the body.`,
    ),
  tags: z.array(z.string()).max(6).describe('Short Arabic topic tags, e.g. company names, sectors, EGX30'),
  sources: z
    .array(z.object({ title: z.string(), url: z.string() }))
    .describe('Real sources actually found via web search — never invented'),
  image: z.object({
    concept: z.string().describe('Arabic description of the feature image: subject, framing, and mood'),
    alt: z.string().describe('Arabic alt text for the feature image'),
    caption: z.string().describe('Arabic caption for the feature image'),
    ratioAndFilename: z.string().describe('Recommended aspect ratio and a suggested filename, e.g. "16:9 — comi-q3-earnings-egx30.jpg"'),
  }),
});

const ReviewSchema = z.object({
  verdict: z.enum(['pass', 'flag']).describe('"flag" if the draft has factual, sourcing, or quality problems worth a human look'),
  notes: z.string().describe('Arabic — what an admin reviewer should check before approving, or why it looks fine'),
});

function buildDiscoverySystemPrompt() {
  return `أنت استراتيجي محتوى مالي وخبير SEO متخصص في البورصة المصرية (EGX)، وظيفتك بناء خطة المحتوى اليومية.

قواعد:
- استخدم أداة البحث على الإنترنت للوصول لآخر أخبار البورصة المصرية فعليًا — ما تخترعش أخبار أو أرقام.
- اختار ${ARTICLES_PER_DAY} زوايا إخبارية مختلفة تمامًا (مؤشرات، إفصاحات شركات، توزيعات أرباح، زيادات رأس مال، قرارات الرقابة المالية، طروحات وإدراجات، أداء قطاعات، محركات اقتصادية كلية) — من غير أي تداخل بين الزوايا.
- كل زاوية لازم تتربط بكلمة مفتاحية عربية مختلفة عالية البحث، وما يتكررش نفس المفتاح في أكتر من زاوية.`;
}

/**
 * Combines the brief's "keyword discovery" and "news sourcing" steps into one
 * research call — both need the same web search, so splitting them into two
 * model calls would double the cost for no real benefit.
 */
export async function discoverTopics({ postDate }) {
  const userMessage = `ابحث عن آخر أخبار البورصة المصرية (EGX) ليوم ${postDate} وابني خطة محتوى من ${ARTICLES_PER_DAY} مقالات: مؤشرات (زي EGX30)، إفصاحات شركات مقيدة كبرى، توزيعات أرباح، زيادات رأس مال، قرارات الرقابة المالية، أخبار طروحات/إدراج، أداء قطاعي، ومحركات اقتصادية كلية مؤثرة على السوق. لكل مقالة حدد الكلمة المفتاحية الأساسية، كلمات مفتاحية ثانوية، والزاوية الإخبارية المحددة اللي هتتغطى.`;

  const { data, raw } = await requestStructuredOR({
    model: BLOG_MODEL,
    schema: TopicPlanSchema,
    schemaName: 'blog_topic_plan',
    maxTokens: 4000,
    system: buildDiscoverySystemPrompt(),
    messages: [{ role: 'user', content: userMessage }],
    webSearch: { engine: 'auto', max_results: 8, max_uses: 10 },
  });

  return { topics: data.topics, raw };
}

function buildArticleSystemPrompt() {
  return `أنت كاتب محتوى مالي وخبير SEO لموقع EGXpert، متخصص في البورصة المصرية (EGX). اكتب مقالة إخبارية/تحليلية واحدة بالعربية الفصحى وبأسلوب مالي احترافي، موجهة لمستثمر مصري عادي مبتدئ في التداول.

قواعد:
- استخدم أداة البحث على الإنترنت للوصول لأخبار ومعلومات حديثة فعلاً عن القصة المحددة المطلوبة — ما تخترعش أرقام أو أحداث أو أسماء شركات أو تواريخ أو اقتباسات.
- كل رقم أو خبر تذكره لازم يكون مبني على مصدر حقيقي رجعت له بالبحث؛ اذكر مصادرك في حقل sources. لو معندكش خبر أو رقم مؤكد، قول كده صراحة بدل ما تخترعه.
- المقالة لازم تكون بين ${MIN_WORDS} و${MAX_WORDS} كلمة بالظبط — عدّ الكلمات والتزم بالحدود.
- استخدم الكلمة المفتاحية الأساسية في العنوان (H1)، في عنوان فرعي واحد على الأقل (H2)، وفي أول 100 كلمة من المقالة. وزّع الكلمات المفتاحية الثانوية في المحتوى من غير حشو.
- التزم بتسلسل عناوين منطقي: H2 للأقسام الرئيسية، H3 للأقسام الفرعية داخلها فقط — من غير قفز في المستويات.
- المقالة موجهة لمستثمر عادي — واضحة ومباشرة، من غير مبالغة أو نصايح استثمارية قاطعة (ده محتوى تحليلي مش توصية).
- ما تكتبش أي خاتمة دعوة لاتخاذ إجراء (CTA) — دي بتتضاف تلقائيًا بعد المقالة.`;
}

/** Runs one generation + review pass for a single topic. */
async function generateArticle({ postDate, topic }) {
  const userMessage = `اكتب مقالة جديدة عن البورصة المصرية ليوم ${postDate}.
الكلمة المفتاحية الأساسية: ${topic.primaryKeyword}
الكلمات المفتاحية الثانوية: ${topic.secondaryKeywords.join('، ')}
الزاوية الإخبارية المطلوبة: ${topic.newsAngle}
ابحث عن التفاصيل الفعلية لهذه القصة تحديدًا (أرقام، تواريخ، تصريحات، مصادر) قبل الكتابة.`;

  const { data, raw } = await requestStructuredOR({
    model: BLOG_MODEL,
    schema: BlogPostSchema,
    schemaName: 'blog_post',
    maxTokens: 6000,
    system: buildArticleSystemPrompt(),
    messages: [{ role: 'user', content: userMessage }],
    webSearch: { engine: 'auto', max_results: 6, max_uses: 8 },
  });

  return { post: data, raw };
}

function countWords(content) {
  const text = content
    .map((b) => (b.type === 'list' ? b.items.join(' ') : b.text))
    .join(' ')
    .trim();
  return text ? text.split(/\s+/).length : 0;
}

/**
 * generateArticle() with one bounded retry if the model missed the
 * 500-1000 word target — the brief requires that range strictly, but asking
 * for unlimited retries against a free model would be an open-ended cost.
 */
async function generateArticleWithinWordCount({ postDate, topic }) {
  let { post, raw } = await generateArticle({ postDate, topic });
  let words = countWords(post.content);

  if (words < MIN_WORDS || words > MAX_WORDS) {
    const direction = words < MIN_WORDS ? `وسّع المقالة (${words} كلمة حاليًا) لتصل بين ${MIN_WORDS} و${MAX_WORDS} كلمة` : `اختصر المقالة (${words} كلمة حاليًا) لتصل بين ${MIN_WORDS} و${MAX_WORDS} كلمة`;
    const retryMessage = `المقالة اللي كتبتها عدد كلماتها ${words}، وده خارج النطاق المطلوب (${MIN_WORDS}-${MAX_WORDS} كلمة). ${direction}، من غير ما تخترع أي معلومة جديدة، وابعت المقالة كاملة تاني بنفس الحقول.`;
    const retry = await requestStructuredOR({
      model: BLOG_MODEL,
      schema: BlogPostSchema,
      schemaName: 'blog_post',
      maxTokens: 6000,
      system: buildArticleSystemPrompt(),
      messages: [
        { role: 'user', content: `اكتب مقالة عن: ${topic.newsAngle} (الكلمة المفتاحية: ${topic.primaryKeyword})` },
        { role: 'assistant', content: JSON.stringify(post) },
        { role: 'user', content: retryMessage },
      ],
      webSearch: { engine: 'auto', max_results: 4, max_uses: 4 },
    });
    post = retry.data;
    raw = retry.raw;
    words = countWords(post.content);
  }

  return { post, raw, words };
}

/** Independent model review of a freshly generated draft — a second opinion before a human sees it. */
export async function reviewBlogPost(post) {
  const userMessage = `راجع المقالة دي قبل ما توصل لمراجعة بشرية. تأكد إن المصادر منطقية ومرتبطة بالمحتوى، وإن مفيش أرقام أو أحداث شكلها مُختلقة، وإن المحتوى مفيدة وليست عامة جدًا.

العنوان: ${post.title}
الملخص: ${post.dek}
المحتوى: ${post.content.map((b) => (b.type === 'list' ? b.items.join(' / ') : b.text)).join('\n')}
المصادر: ${post.sources.map((s) => `${s.title} (${s.url})`).join(', ') || 'لا يوجد'}`;

  const { data, raw } = await requestStructuredOR({
    model: BLOG_REVIEW_MODEL,
    schema: ReviewSchema,
    schemaName: 'blog_review',
    maxTokens: 1000,
    system: 'أنت مراجع محتوى مالي دقيق. مهمتك تقييم مسودة مقالة قبل نشرها — لاحظ أي مشكلة في الدقة أو المصادر أو الجودة.',
    messages: [{ role: 'user', content: userMessage }],
  });

  return { review: data, raw };
}

/** Appends the exact required CTA as its own paragraph block — never through the model, so it can never be paraphrased or altered. */
function withCta(content) {
  return [...content, { type: 'paragraph', text: CTA_TEXT }];
}

async function generateReviewAndStore({ postDate, batchIndex, topic }) {
  const { post, raw: genRaw, words } = await generateArticleWithinWordCount({ postDate, topic });

  // The review is a second opinion, not a gate a human bypasses anyway —
  // every draft still needs manual approval before it's public. So a
  // review-model hiccup (rate limits on a free model are common) should
  // never throw away an already-paid-for generation; it just means this one
  // draft reaches the admin queue without that extra signal.
  let review = null;
  let reviewModel = null;
  try {
    const reviewResult = await reviewBlogPost(post);
    review = reviewResult.review;
    reviewModel = reviewResult.raw.model;
  } catch (err) {
    console.error(`reviewBlogPost failed for batch ${batchIndex} — storing draft without an automated review:`, err);
    review = { verdict: 'flag', notes: `المراجعة الآلية فشلت (${err.message}) — راجع المحتوى يدويًا بعناية أكبر.` };
  }

  if (words < MIN_WORDS || words > MAX_WORDS) {
    const note = `تنبيه: عدد كلمات المقالة ${words}، خارج النطاق المطلوب (${MIN_WORDS}-${MAX_WORDS}). ${review.notes}`;
    review = { ...review, verdict: 'flag', notes: note };
  }

  const slug = `${post.slug.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'egx-update'}-${postDate}-${batchIndex}`;

  const inserted = await insertBlogPostDraft({
    postDate,
    batchIndex,
    slug,
    primaryKeyword: topic.primaryKeyword,
    secondaryKeywords: topic.secondaryKeywords,
    title: post.title,
    metaDescription: post.metaDescription,
    dek: post.dek,
    content: withCta(post.content),
    tags: post.tags,
    sources: post.sources,
    image: post.image,
    generationModel: genRaw.model,
    generationUsage: genRaw.usage,
    reviewModel,
    review,
  });
  return inserted;
}

// One in-flight batch per postDate within this process — stops two racing
// cron/admin calls from each paying for their own generation before the
// first's inserts land.
const inFlight = new Map();

/**
 * The entry point every route should use. Returns today's batch of articles
 * (from storage where already generated, generating whatever is still
 * missing) for postDate. Runs the ten articles sequentially — free-tier
 * OpenRouter models are rate-sensitive, and a failure partway through still
 * leaves the earlier articles stored so a retry only pays for what's left.
 */
export async function getOrGenerateDailyBlogBatch({ postDate = new Date().toISOString().slice(0, 10) } = {}) {
  const existing = await getBlogPostsForDate(postDate);
  if (existing.length >= ARTICLES_PER_DAY) return existing;

  if (inFlight.has(postDate)) return inFlight.get(postDate);

  const task = (async () => {
    const byBatchIndex = new Map(existing.map((p) => [p.batch_index, p]));
    const { topics } = await discoverTopics({ postDate });

    const results = [];
    for (let i = 0; i < ARTICLES_PER_DAY; i++) {
      const batchIndex = i + 1;
      const already = byBatchIndex.get(batchIndex);
      if (already) {
        results.push(already);
        continue;
      }
      const topic = topics[i];
      try {
        const inserted = await generateReviewAndStore({ postDate, batchIndex, topic });
        // Someone else's insert may have won the race — re-read either way so
        // every caller sees exactly what ended up stored.
        results.push(inserted ?? (await getBlogPostByBatch(postDate, batchIndex)));
      } catch (err) {
        console.error(`Article ${batchIndex}/${ARTICLES_PER_DAY} for ${postDate} failed — continuing with the rest of the batch:`, err);
      }
    }
    return results;
  })();
  inFlight.set(postDate, task);
  try {
    return await task;
  } finally {
    inFlight.delete(postDate);
  }
}
